SELECT CAST(result.c0 AS INTEGER) AS "output_key", CAST(result.c1 AS BIGINT) AS "input_version", CAST(result.c2 AS INTEGER) AS "value", CAST(result.c3 AS BOOLEAN) AS "deleted" FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5 FROM (SELECT "output_key" AS c0, "input_version" AS c1, "value" AS c2, "deleted" AS c3 FROM "candidates") l INNER JOIN (SELECT t.c0 AS c0, CAST(MAX(t.c1) AS BIGINT) AS c1 FROM (SELECT t.c0 AS c0, t.c1 AS c1 FROM (SELECT "output_key" AS c0, "input_version" AS c1, "value" AS c2, "deleted" AS c3 FROM "candidates") t) t GROUP BY t.c0) r ON ((l.c0 = r.c0) AND (l.c1 = r.c1))) t) result;
